function parseVCard(text: string): ParsedContact[] { return text.split(/END:VCARD/i).map((chunk) => ({ display_name: chunk.match(/(?:^|
)FN[^:]*:(.+)/i)?.[1]?.trim() ?? null, email: chunk.match(/(?:^|
)EMAIL[^:]*:(.+)/i)?.[1]?.trim() ?? null, phone: chunk.match(/(?:^|
)TEL[^:]*:(.+)/i)?.[1]?.trim() ?? null })).filter((item) => item.display_name || item.email || item.phone); }
function parseCsv(text: string): ParsedContact[] { const rows=text.split(/?
/).map((r)=>r.trim()).filter(Boolean); if(!rows.length)return[]; const headers=rows[0].split(",").map((h)=>h.trim().toLowerCase()); const idx=(names:string[])=>headers.findIndex((h)=>names.includes(h)); const ni=idx(["name","display_name","full name","fullname"]), ei=idx(["email","e-mail"]), pi=idx(["phone","mobile","telephone","tel"]); return rows.slice(1).map((row)=>{const c=row.split(",").map((x)=>x.trim().replace(/^"|"$/g,"")); return {display_name:ni>=0?c[ni]||null:null,email:ei>=0?c[ei]||null:null,phone:pi>=0?c[pi]||null:null};

